import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

String read(String path) => File(path).readAsStringSync();

const ci = '.github/workflows/ci.yml';
const ptyJobId = 'pty-integration-linux';

/// The digest pin every upload-artifact step (retry included) must carry —
/// the same line test/release_hygiene_test.dart pins repo-wide (gh-995:
/// the gate's download-artifact digest-validates every download).
const artifactPin =
    'actions/upload-artifact@043fb46d1a93c77aae656e7c1c64a875d1fc6a0a';

List<YamlMap> jobSteps(String jobId) {
  final root = loadYaml(read(ci)) as YamlMap;
  final jobs = root['jobs'] as YamlMap;
  final job = jobs[jobId];
  if (job is! YamlMap) throw StateError('job $jobId missing from $ci');
  return (job['steps'] as YamlList).whereType<YamlMap>().toList();
}

/// The upload steps of [steps]: every step that invokes upload-artifact.
List<YamlMap> uploadSteps(List<YamlMap> steps) => steps
    .where((step) => (step['uses']?.toString() ?? '').startsWith('actions/upload-artifact@'))
    .toList();

void main() {
  group('gh-1412 — pty-integration-linux artifact uploads ride a retry', () {
    final steps = jobSteps(ptyJobId);
    final uploads = uploadSteps(steps);

    test('the leg still carries the three evidence uploads', () {
      expect(uploads, hasLength(3), reason: 'integration-json, junit, '
          'pty-coverage — the guards below key on exactly these');
    });

    test('AC1: every upload step carries an id the retry can reference', () {
      for (final step in uploads) {
        expect(
          step['id'],
          isA<String>(),
          reason: 'upload step "${step['name'] ?? step['uses']}" lost its '
              'id — the gh-1412 retry keys on steps.<id>.outcome',
        );
      }
    });

    test('AC2: each upload is followed by an overwrite:true retry step', () {
      for (var i = 0; i < steps.length; i++) {
        final step = steps[i];
        if (!(step['uses']?.toString() ?? '').startsWith('actions/upload-artifact@')) {
          continue;
        }
        final id = step['id'] as String;
        expect(
          i + 1,
          lessThan(steps.length),
          reason: 'upload "$id" has no retry step after it',
        );
        final retry = steps[i + 1];
        expect(
          retry['uses'],
          artifactPin,
          reason: 'the retry of "$id" must ride the same digest-validating '
              'upload-artifact line (gh-995 pin, release_hygiene_test.dart)',
        );
        expect(
          retry['if']?.toString(),
          contains("steps.$id.outcome == 'failure'"),
          reason: 'the retry of "$id" must fire only on the failed upload',
        );
        expect(
          (retry['with'] as YamlMap)['overwrite'],
          true,
          reason: 'the retry of "$id" must overwrite the half-registered '
              'artifact a finalize-class failure leaves behind — with the '
              'default overwrite:false the retry dies on "already exists"',
        );
        expect(
          (retry['with'] as YamlMap)['name'],
          (step['with'] as YamlMap)['name'],
          reason: 'the retry of "$id" must re-upload the SAME artifact name '
                  'the gate below downloads',
        );
      }
    });

    test('AC3: retries stay always()-reachable and never continue-on-error',
        () {
      for (var i = 0; i < steps.length; i++) {
        final step = steps[i];
        if (!(step['uses']?.toString() ?? '').startsWith('actions/upload-artifact@')) {
          continue;
        }
        final retry = steps[i + 1];
        expect(
          retry['if']?.toString(),
          contains('always()'),
          reason: 'the retry after "${step['id']}" must stay reachable on red '
              'legs — the evidence uploads run if: always() so a red run '
              'keeps its timing/coverage evidence (the retry inherits that '
              'contract)',
        );
        expect(
          retry['continue-on-error'],
          isNot(true),
          reason: 'a genuinely dead blob endpoint must still fail the shard '
              'loudly — the pty-coverage-gate asserts on these artifacts',
        );
      }
    });
  });
}
