          continue;
        }
        final retry = steps[i + 1];
        expect(
          retry['if']?.toString(),
          contains('always()'),
          reason: 'the retry after "${step['id']}" must stay reachable on red '
              'legs — the evidence uploads run if: always() so a red run '
              'keeps its timing/coverage evidence (the retry inherits that '
              'contract)',
        );
        expect(
          retry['continue-on-error'],
          isNot(true),
          reason: 'a genuinely dead blob endpoint must still fail the shard '
              'loudly — the pty-coverage-gate asserts on these artifacts',
        );
