    final steps = jobSteps(ptyJobId);
    // Primary uploads only — the retries are keyed on a failed outcome,
    // a primary upload never is.
    final primaries = [
      for (final step in steps)
        if (isUploadStep(step) && !isRetryStep(step)) step,
    ];
    final retries = [
      for (final step in steps)
